import {classifyPrediction,cropRegion,loadBundledModel,loadRemoteModel,loadLocalModel} from './model.js';
import {validateRegions,regionWarnings} from './regions.js';
import {countVehicles} from './counting.js';
import {preparePhoto} from './image-input.js';
import {inspectCanvas,QUALITY_VERSION} from './quality.js';
import {fingerprintFile} from './evaluation.js';

const $=id=>document.getElementById(id);
const PROFILE_KEY='parking-count-profiles-v2';
const PREPROCESSING={version:'roi-rgb224-v1',resize:'complete selected rectangle to224x224',normalization:'TM RGB/127-1',quality:QUALITY_VERSION};
const statusLabels={occupied:'차량 있음',empty:'빈자리',uncertain:'확인 필요'};
let photo=null,imageHash=null,fileName='',rois=[],selectedId=null,editMode=null,drag=null,profileReference=null;
let model=null,emptyClass='빈자리',occupiedClass='사용 중',results=[],lastRun=null,busy=false,analysisActive=false,cancelRequested=false,revision=0;

function feedback(message,error=false){$('feedback').textContent=message;$('feedback').classList.toggle('error',error);$('feedback').hidden=!message;}
function setBusy(value){busy=value;document.querySelectorAll('[data-lock],.roi,.region-chip').forEach(el=>el.disabled=value);$('cancel-analysis').hidden=!(value&&analysisActive);$('cancel-analysis').disabled=false;if(!value){$('analyze-text').textContent='차량 수 확인하기';$('progress-track').hidden=true;updateAvailability();}}
function updateAvailability(){if(busy)return;document.querySelectorAll('.roi,.region-chip').forEach(el=>el.disabled=false);$('add-region').disabled=!photo||rois.length>=100;$('move-region').disabled=!photo||!selectedId;$('delete-region').disabled=!selectedId;$('apply-coordinates').disabled=!selectedId;$('analyze-btn').disabled=!photo||!rois.length;$('export-regions').disabled=!rois.length;$('clear-regions').disabled=!rois.length;$('save-profile').disabled=!rois.length;}
function invalidate(message){revision++;results=[];lastRun=null;$('roi-confirmed').checked=false;$('analysis-progress').textContent='';renderResults();renderRegions();if(message)feedback(message);}
function setEditMode(mode){editMode=mode;drag=null;$('draw-box').hidden=true;$('image-stage').classList.toggle('is-editing',!!mode);$('editing-hint').hidden=!mode;$('editing-hint').textContent=mode==='add'?'주차칸 하나를 드래그해서 추가하세요':(selectedId||'선택한 칸')+' 영역을 다시 드래그하세요';$('finish-editing').hidden=!mode;$('add-region').classList.toggle('primary',mode==='add');$('region-editor-note').textContent=!photo?'사진을 먼저 선택해주세요.':mode==='add'?'사진 위에서 한 칸씩 드래그하세요. 같은 칸을 중복 지정하지 마세요.':mode==='edit'?'선택한 주차칸의 전체 영역을 사진 위에서 드래그하세요.':rois.length?'칸을 선택하면 위치를 바꾸거나 삭제할 수 있습니다.':'‘주차칸 추가’를 누르고 사진 위를 드래그하세요.';}
function nextId(){for(let i=1;i<=100;i++)if(!rois.some(r=>r.id==='A'+i))return 'A'+i;throw new Error('주차칸은 최대100개까지 지정할 수 있습니다.');}
function selectedRegion(){return rois.find(r=>r.id===selectedId);}
function regionChanged(message){invalidate(message);setEditMode(editMode);renderEditor();updateAvailability();}
function renderEditor(){const list=$('region-list');list.replaceChildren();for(const r of rois){const b=document.createElement('button');b.className='region-chip';b.textContent=r.id;b.setAttribute('aria-pressed',String(r.id===selectedId));b.disabled=busy;b.onclick=()=>{selectedId=r.id;setEditMode(null);renderEditor();renderRegions();};list.append(b);}const r=selectedRegion();$('selected-region-editor').hidden=!r;if(r){$('selected-region-name').textContent=r.id+' 위치';for(const key of ['x','y','w','h'])$('roi-'+key).value=String(Math.round(r[key]*10000)/100);}const warnings=rois.length?regionWarnings(rois):[];$('region-warning').hidden=!warnings.length;$('region-warning').textContent=warnings.map(w=>w.message).join(' ');updateAvailability();}
function renderRegions(){const layer=$('roi-layer');layer.replaceChildren();rois.forEach((r,i)=>{const b=document.createElement('button');b.type='button';b.className='roi '+(results[i]?.status||'pending')+(r.id===selectedId?' selected':'');Object.assign(b.style,{left:r.x*100+'%',top:r.y*100+'%',width:r.w*100+'%',height:r.h*100+'%'});b.setAttribute('aria-label',r.id+' '+(statusLabels[results[i]?.status]||'주차칸')+' 선택');b.disabled=busy;const label=document.createElement('span');label.className='roi-label';label.textContent=r.id;b.title=r.id+' · '+(statusLabels[results[i]?.status]||'주차칸');b.append(label);b.onclick=()=>{if(busy)return;selectedId=r.id;setEditMode(null);$('regions-panel').open=true;renderRegions();renderEditor();};layer.append(b);});$('region-summary').hidden=!photo;$('region-count').textContent=rois.length?'총 '+rois.length+'칸 지정 · 각 칸을 따로 분석':'지정된 주차칸이 없습니다.';}
function renderResults(){const hasResults=results.length>0;const counts=hasResults?countVehicles(results):null;$('count-label').textContent=counts?(counts.exact?'차량':'확인된 차량'):photo?'주차칸을 확인하고 분석하세요.':'분석할 사진을 선택하세요.';$('vehicle-count').textContent=counts?String(counts.occupied):'—';$('count-description').textContent=counts?(counts.exact?'AI 판정 · 지정한 '+counts.total+'개 주차칸 기준':'애매한 칸을 제외하고 확인한 차량 수입니다.'):'지정한 주차칸 안의 차량 수를 확인합니다.';$('count-range').hidden=!counts||counts.exact;$('count-range').textContent=counts&&!counts.exact?'확인 필요 '+counts.uncertain+'칸을 포함하면 '+counts.min+'~'+counts.max+'대':'';$('result-breakdown').hidden=!hasResults;if(counts){$('total-count').textContent=counts.total;$('empty-count').textContent=counts.empty;$('uncertain-count').textContent=counts.uncertain;}$('export-result').hidden=!hasResults;$('slot-results').hidden=!hasResults;const cards=$('slot-cards');cards.replaceChildren();if(hasResults)results.forEach((r,i)=>{const card=document.createElement('article');card.className='slot-card '+r.status;const top=document.createElement('div');top.className='slot-top';const id=document.createElement('strong');id.textContent=r.id;const badge=document.createElement('span');badge.className='slot-badge';badge.textContent=statusLabels[r.status];top.append(id,badge);card.append(top);try{const crop=cropRegion($('parking-image'),rois[i]);crop.className='slot-crop';crop.setAttribute('role','img');crop.setAttribute('aria-label',r.id+' 모델에 입력한 주차칸');card.append(crop);}catch{}const probability=document.createElement('p');probability.className='slot-probability';probability.textContent=r.prediction_skipped?r.reason:'최고 예측 확률 '+(r.confidence>=.999?'99.9%+':(r.confidence*100).toFixed(1)+'%');card.append(probability);cards.append(card);});}
function download(name,data){const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function aspectRatio(){return photo?photo.width/photo.height:null;}
function cleanProfile(value){const regions=validateRegions(value?.rois);const threshold=Number(value?.threshold);const aspect=Number(value?.aspect_ratio);return {rois:regions,threshold:Number.isInteger(threshold)&&threshold>=50&&threshold<=99?threshold:85,aspect_ratio:Number.isFinite(aspect)&&aspect>0?aspect:null,image_width:Number.isInteger(value?.image_width)&&value.image_width>0?value.image_width:null,image_height:Number.isInteger(value?.image_height)&&value.image_height>0?value.image_height:null};}
function readProfiles(){const clean=Object.create(null);let source;try{source=JSON.parse(localStorage.getItem(PROFILE_KEY)||'null');if(!source||typeof source!=='object'||Array.isArray(source)){source=JSON.parse(localStorage.getItem('parking-four-profiles')||'{}');}for(const [name,value] of Object.entries(source)){if(name.length<1||name.length>60||Object.keys(clean).length>=20)continue;try{clean[name]=cleanProfile(value);}catch{}}}catch{}return clean;}
function renderProfiles(selected=''){const select=$('profile-select');select.replaceChildren(new Option('주차장 선택',''));for(const name of Object.keys(readProfiles()).sort())select.append(new Option(name,name));select.value=selected;}
function persistProfiles(profiles){try{localStorage.setItem(PROFILE_KEY,JSON.stringify(profiles));return true;}catch{feedback('브라우저에 저장하지 못했습니다. ‘영역 JSON 저장’으로 설정을 보관할 수 있습니다.',true);return false;}}
function applyRegions(value,message){rois=validateRegions(value);selectedId=rois[0]?.id||null;setEditMode(null);regionChanged(message);}

async function uploadPhoto(file){if(busy||!file)return false;if(!['image/jpeg','image/png','image/webp'].includes(file.type)){feedback('JPG, PNG, WebP 사진을 선택해주세요. HEIC 사진은 JPG로 변환한 뒤 사용할 수 있습니다.',true);return false;}setBusy(true);let next=null,timer;const image=$('parking-image'),previousSrc=image.getAttribute('src');try{next=await preparePhoto(file);const hash=await fingerprintFile(file);image.src=next.url;await Promise.race([image.decode(),new Promise((_,reject)=>{timer=setTimeout(()=>reject(new Error('사진을 표시하는 시간이 초과됐습니다. 다른 사진을 선택해주세요.')),20000);})]);photo?.dispose();photo=next;next=null;imageHash=hash;fileName=file.name;image.alt='선택한 주차장 사진';$('upload-placeholder').hidden=true;$('image-stage').hidden=false;$('image-caption').textContent=file.name+' · '+photo.width+' × '+photo.height;$('regions-panel').open=rois.length===0;setEditMode(null);invalidate(rois.length?'사진을 불러왔습니다. 촬영 위치와 주차칸 영역이 같은지 확인해주세요.':'사진을 불러왔습니다. ‘주차칸 추가’로 셀 자리를 지정해주세요.');renderEditor();if(profileReference?.aspect_ratio&&Math.abs(aspectRatio()/profileReference.aspect_ratio-1)>.05)feedback('저장한 주차장 사진과 화면 비율이 다릅니다. 촬영 위치와 주차칸 영역을 다시 맞춰주세요.',true);return true;}catch(error){if(previousSrc)image.src=previousSrc;else image.removeAttribute('src');next?.dispose();feedback(error.message||'사진을 읽지 못했습니다.',true);return false;}finally{clearTimeout(timer);setBusy(false);}}
function inferClasses(classes){const ec=classes.find(c=>/^(빈자리|empty|vacant|free|unoccupied)$/i.test(c.trim()));emptyClass=ec||classes[0];occupiedClass=classes.find(c=>c!==emptyClass);for(const id of ['empty-class','occupied-class']){$(id).replaceChildren(...classes.map(c=>new Option(c,c)));}$('empty-class').value=emptyClass;$('occupied-class').value=occupiedClass;$('class-mapping').hidden=false;}
function modelIdentity(){return model?{name:model.name,source:model.source||null,version:model.version||null,sha256:model.sha256||null,empty_class:emptyClass,occupied_class:occupiedClass}:null;}
function showModel(){const text=model?'모델 준비됨':'학습한 주차칸 모델 사용';$('model-status').textContent=text;$('model-description').textContent=model?model.name:'기존에 학습한 빈자리 / 사용 중 모델을 사용합니다.';}
async function loadSelectedModel(){const source=$('model-source').value;return source==='url'?loadRemoteModel($('model-url').value):source==='files'?loadLocalModel($('model-files').files):loadBundledModel();}
async function connectModel(){if(busy)return;setBusy(true);$('model-message').textContent='모델을 불러오는 중입니다…';let next;try{next=await loadSelectedModel();model?.dispose();model=next;next=null;inferClasses(model.classes);invalidate();showModel();$('model-message').textContent='모델을 연결했습니다. 빈자리 / 사용 중 클래스가 맞는지 확인해주세요.';feedback('모델을 연결했습니다. 사진과 주차칸 영역을 확인하고 분석하세요.');}catch(error){next?.dispose();$('model-message').textContent=error.message;feedback('모델 연결 실패: '+error.message,true);}finally{setBusy(false);}}
async function analyze(){if(busy)return;if(!photo)return feedback('사진을 먼저 선택해주세요.',true);try{rois=validateRegions(rois);}catch(error){$('regions-panel').open=true;return feedback(error.message,true);}if(!$('roi-confirmed').checked){$('roi-confirmed').focus();return feedback('영역이 서로 다른 주차칸에 맞는지 확인한 뒤 체크해주세요.',true);}setEditMode(null);const startRevision=revision;const threshold=Number($('threshold').value)/100;const started=performance.now();analysisActive=true;cancelRequested=false;setBusy(true);results=[];lastRun=null;renderResults();renderRegions();feedback('');$('progress-track').hidden=false;$('progress-fill').style.width='0%';let nextModel;try{if(!model){$('analyze-text').textContent='학습한 모델 준비 중…';$('analysis-progress').textContent='첫 분석을 위해 기본 모델을 불러옵니다.';nextModel=await loadSelectedModel();if(cancelRequested){nextModel.dispose();nextModel=null;throw new Error('분석을 취소했습니다.');}model=nextModel;nextModel=null;inferClasses(model.classes);showModel();}await $('parking-image').decode();const nextResults=[];for(let i=0;i<rois.length;i++){if(cancelRequested)throw new Error('분석을 취소했습니다.');$('analyze-text').textContent=rois[i].id+' 분석 중…';$('analysis-progress').textContent=(i+1)+' / '+rois.length+'칸 · 주차칸을 잘라 확인하고 있습니다.';await new Promise(resolve=>requestAnimationFrame(()=>setTimeout(resolve,0)));const canvas=cropRegion($('parking-image'),rois[i]);const quality=inspectCanvas(canvas);const result=quality.valid?classifyPrediction(await model.predict(canvas),threshold,emptyClass,occupiedClass):{status:'uncertain',confidence:0,probabilities:{empty:null,occupied:null},prediction_skipped:true,reason:quality.reasons.map(r=>r.message).join(' ')};nextResults.push({...result,id:rois[i].id,quality});$('progress-fill').style.width=((i+1)/rois.length*100)+'%';}if(cancelRequested)throw new Error('분석을 취소했습니다.');if(startRevision!==revision)return;results=nextResults;const duration=Math.round(performance.now()-started);lastRun={schema_version:3,task:'occupied-parking-slot-count',scope:'지정한 주차칸 안의 차량 수',assumption:'한 주차칸에 차량 한 대',image_name:fileName,image_sha256:imageHash,image_width:photo.width,image_height:photo.height,analyzed_at:new Date().toISOString(),analysis_duration_ms:duration,threshold,model:modelIdentity(),preprocessing:PREPROCESSING,rois:rois.map(r=>({...r})),counts:countVehicles(results),results};renderResults();renderRegions();$('analysis-progress').textContent=rois.length+'칸 · '+(duration/1000).toFixed(1)+'초에 분석 완료';feedback(lastRun.counts.uncertain?'확인 필요인 칸은 최종 대수를 확정하지 않고 별도로 표시했습니다.':'지정한 주차칸의 차량 수를 확인했습니다.');}catch(error){nextModel?.dispose();results=[];lastRun=null;renderResults();renderRegions();$('analysis-progress').textContent=cancelRequested?'분석을 취소했습니다. 다시 확인할 수 있습니다.':'분석을 완료하지 못했습니다.';feedback(cancelRequested?'분석을 취소했습니다. 준비된 사진으로 다시 분석할 수 있습니다.':'분석 실패: '+error.message,!cancelRequested);}finally{analysisActive=false;setBusy(false);}}

const stage=$('image-stage');function point(event){const box=stage.getBoundingClientRect();return {x:Math.max(0,Math.min(1,(event.clientX-box.left)/box.width)),y:Math.max(0,Math.min(1,(event.clientY-box.top)/box.height))};}
stage.addEventListener('pointerdown',event=>{if(!editMode||!photo||busy||event.button>0)return;event.preventDefault();drag=point(event);stage.setPointerCapture(event.pointerId);});
stage.addEventListener('pointermove',event=>{if(!drag)return;const end=point(event);$('draw-box').hidden=false;Object.assign($('draw-box').style,{left:Math.min(drag.x,end.x)*100+'%',top:Math.min(drag.y,end.y)*100+'%',width:Math.abs(end.x-drag.x)*100+'%',height:Math.abs(end.y-drag.y)*100+'%'});});
stage.addEventListener('pointerup',event=>{if(!drag)return;const end=point(event);const proposed={id:editMode==='add'?nextId():selectedId,x:Math.min(drag.x,end.x),y:Math.min(drag.y,end.y),w:Math.abs(end.x-drag.x),h:Math.abs(end.y-drag.y)};drag=null;$('draw-box').hidden=true;if(proposed.w<.015||proposed.h<.015){feedback('주차칸 전체가 들어가도록 조금 더 크게 드래그해주세요.',true);return;}try{const next=editMode==='add'?[...rois,proposed]:rois.map(r=>r.id===selectedId?proposed:r);rois=validateRegions(next);selectedId=proposed.id;regionChanged(proposed.id+' 주차칸을 지정했습니다.');if(rois.length>=100)setEditMode(null);}catch(error){feedback(error.message,true);}});
stage.addEventListener('pointercancel',()=>{drag=null;$('draw-box').hidden=true;});
$('camera-btn').onclick=()=>$('camera-file').click();$('upload-btn').onclick=()=>$('image-file').click();for(const id of ['camera-file','image-file'])$(id).onchange=event=>{const file=event.target.files[0];event.target.value='';uploadPhoto(file);};
$('edit-regions').onclick=()=>{$('regions-panel').open=!$('regions-panel').open;if($('regions-panel').open){renderEditor();$('regions-panel').scrollIntoView({behavior:'smooth',block:'nearest'});}};
$('add-region').onclick=()=>{if(!photo)return;setEditMode(editMode==='add'?null:'add');if(editMode)stage.scrollIntoView({behavior:'smooth',block:'center'});};
$('move-region').onclick=()=>{if(!selectedId||!photo)return;setEditMode(editMode==='edit'?null:'edit');if(editMode)stage.scrollIntoView({behavior:'smooth',block:'center'});};
$('finish-editing').onclick=()=>setEditMode(null);$('regions-panel').addEventListener('toggle',()=>{if(!$('regions-panel').open)setEditMode(null);});
$('delete-region').onclick=()=>{if(busy)return;const id=selectedId;rois=rois.filter(r=>r.id!==id);selectedId=rois[0]?.id||null;setEditMode(null);regionChanged(id+' 주차칸을 삭제했습니다.');};
$('clear-regions').onclick=()=>{if(busy)return;rois=[];selectedId=null;setEditMode(null);regionChanged('주차칸 영역을 모두 지웠습니다.');};
$('apply-coordinates').onclick=()=>{if(busy||!selectedId)return;try{const next={id:selectedId};for(const key of ['x','y','w','h']){const raw=$('roi-'+key).value;next[key]=raw.trim()===''?NaN:Number(raw)/100;}rois=validateRegions(rois.map(r=>r.id===selectedId?next:r));setEditMode(null);regionChanged(selectedId+' 위치를 적용했습니다.');}catch(error){feedback(error.message,true);}};
$('save-profile').onclick=()=>{if(busy)return;const name=$('profile-name').value.trim();if(!name||name.length>60)return feedback('주차장 이름을 1~60자로 입력해주세요.',true);try{const profiles=readProfiles();if(!Object.hasOwn(profiles,name)&&Object.keys(profiles).length>=20)throw new Error('주차장 설정은 최대20개까지 저장할 수 있습니다.');profiles[name]={rois:validateRegions(rois),threshold:Number($('threshold').value),aspect_ratio:aspectRatio(),image_width:photo?.width||null,image_height:photo?.height||null};profileReference=profiles[name];if(persistProfiles(profiles)){renderProfiles(name);feedback('주차칸 '+rois.length+'개를 ‘'+name+'’ 설정으로 저장했습니다.');}}catch(error){feedback(error.message,true);}};
$('profile-select').onchange=()=>{if(busy)return;const name=$('profile-select').value,p=readProfiles()[name];if(!p)return;try{profileReference=p;applyRegions(p.rois,'저장된 주차칸을 불러왔습니다. 같은 촬영 위치인지 사진에서 확인해주세요.');$('threshold').value=p.threshold;$('threshold-value').textContent=p.threshold+'%';$('profile-name').value=name;if(photo&&p.aspect_ratio&&Math.abs(aspectRatio()/p.aspect_ratio-1)>.05)feedback('저장한 사진과 화면 비율이 다릅니다. 촬영 위치와 영역을 다시 맞춰주세요.',true);}catch(error){feedback(error.message,true);}};
$('delete-profile').onclick=()=>{if(busy)return;const name=$('profile-select').value;if(!name)return;const profiles=readProfiles();delete profiles[name];if(persistProfiles(profiles)){profileReference=null;renderProfiles();feedback('저장된 설정을 삭제했습니다. 현재 사진의 영역은 유지됩니다.');}};
$('export-regions').onclick=()=>{try{download('parking-count-regions.json',{schema_version:2,coordinate_system:'normalized',rois:validateRegions(rois),threshold:Number($('threshold').value),aspect_ratio:aspectRatio(),image_width:photo?.width||null,image_height:photo?.height||null});}catch(error){feedback(error.message,true);}};
$('region-file').onchange=async event=>{const file=event.target.files[0];event.target.value='';if(!file||busy)return;setBusy(true);try{if(file.size>100000)throw new Error('영역 설정 파일은100KB 이하로 선택해주세요.');const value=JSON.parse(await file.text());const next=validateRegions(value.rois||value);profileReference={aspect_ratio:Number.isFinite(value.aspect_ratio)?value.aspect_ratio:null,image_width:value.image_width||null,image_height:value.image_height||null};applyRegions(next,'영역 설정을 불러왔습니다. 사진의 주차칸에 맞는지 확인해주세요.');if(Number.isInteger(value.threshold)&&value.threshold>=50&&value.threshold<=99){$('threshold').value=value.threshold;$('threshold-value').textContent=value.threshold+'%';}}catch(error){feedback('영역 불러오기 실패: '+error.message,true);}finally{setBusy(false);renderEditor();}};
$('threshold').oninput=()=>{$('threshold-value').textContent=$('threshold').value+'%';invalidate('판정 기준을 바꿨습니다. 영역을 확인하고 다시 분석해주세요.');};
$('model-source').onchange=()=>{$('url-panel').hidden=$('model-source').value!=='url';$('files-panel').hidden=$('model-source').value!=='files';};
$('load-model').onclick=connectModel;$('apply-mapping').onclick=()=>{if(busy||!model)return;if($('empty-class').value===$('occupied-class').value)return feedback('빈자리와 사용 중 클래스를 서로 다르게 선택해주세요.',true);emptyClass=$('empty-class').value;occupiedClass=$('occupied-class').value;invalidate('클래스 연결을 적용했습니다. 사진을 다시 분석해주세요.');$('model-message').textContent='클래스 연결을 적용했습니다.';};
$('analyze-btn').onclick=analyze;$('cancel-analysis').onclick=()=>{cancelRequested=true;model?.cancel?.();$('cancel-analysis').disabled=true;$('analysis-progress').textContent='분석을 취소하고 있습니다…';};
$('export-result').onclick=()=>{if(lastRun)download('parking-vehicle-count.json',lastRun);};
$('example-btn').onclick=async()=>{if(busy)return;setBusy(true);let file,config;const controller=new AbortController();const timer=setTimeout(()=>controller.abort(),20000);try{const [image,regions]=await Promise.all([fetch('./examples/parking.jpg',{signal:controller.signal}),fetch('./examples/regions.json',{signal:controller.signal})]);if(!image.ok||!regions.ok)throw new Error('예제 파일을 불러오지 못했습니다.');file=new File([await image.blob()],'PKLot-주차장-예제.jpg',{type:'image/jpeg'});config=await regions.json();}catch(error){feedback(error.name==='AbortError'?'예제 연결 시간이 초과됐습니다. 다시 시도해주세요.':error.message,true);}finally{clearTimeout(timer);setBusy(false);}if(!file)return;const loaded=await uploadPhoto(file);if(!loaded)return;try{profileReference=null;applyRegions(config.rois||config,'학습 자료와 같은 방식으로 지정한 실제 주차장 예제를 분석합니다.');$('roi-confirmed').checked=true;$('regions-panel').open=false;$('image-caption').textContent+=' · 공개 PKLot 예제';await analyze();}catch(error){feedback(error.message,true);}};
const panel=document.querySelector('.photo-panel');for(const type of ['dragenter','dragover'])panel.addEventListener(type,event=>{event.preventDefault();if(!busy)panel.classList.add('drag-over');});panel.addEventListener('dragleave',event=>{if(!panel.contains(event.relatedTarget))panel.classList.remove('drag-over');});panel.addEventListener('drop',event=>{event.preventDefault();panel.classList.remove('drag-over');uploadPhoto(event.dataTransfer.files[0]);});
renderProfiles();renderEditor();renderRegions();renderResults();setEditMode(null);showModel();updateAvailability();
